import{_ as n,o as e,c as i,a3 as t}from"./chunks/framework.BvvarXmc.js";const d=JSON.parse('{"title":"Pencatatan Pembayaran di Kasir (Loket Sekolah)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-keuangan/pembayaran-kasir.md","filePath":"panduan-keuangan/pembayaran-kasir.md","lastUpdated":null}'),r={name:"panduan-keuangan/pembayaran-kasir.md"};function s(l,a,o,u,k,m){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="pencatatan-pembayaran-di-kasir-loket-sekolah" tabindex="-1">Pencatatan Pembayaran di Kasir (Loket Sekolah) <a class="header-anchor" href="#pencatatan-pembayaran-di-kasir-loket-sekolah" aria-label="Permalink to &quot;Pencatatan Pembayaran di Kasir (Loket Sekolah)&quot;">​</a></h1><p>Panduan ini digunakan oleh petugas loket pembayaran / kasir TU saat siswa atau orang tua datang langsung ke sekolah untuk membayar dengan uang tunai.</p><hr><h2 id="_1-langkah-transaksi-pembayaran-tunai" tabindex="-1">1. Langkah Transaksi Pembayaran Tunai <a class="header-anchor" href="#_1-langkah-transaksi-pembayaran-tunai" aria-label="Permalink to &quot;1. Langkah Transaksi Pembayaran Tunai&quot;">​</a></h2><ol><li>Buka menu <strong>Keuangan</strong> <strong>Kasir Pembayaran (POS Loket)</strong>.</li><li>Cari data siswa dengan salah satu cara berikut: <ul><li><strong>Ketik NIS / Nama Siswa</strong> di kolom pencarian.</li><li>Atau tempelkan <strong>Kartu Pelajar (RFID / Barcode)</strong> siswa ke alat scanner.</li></ul></li><li>Layar akan menampilkan profil siswa beserta daftar seluruh tagihan yang belum dibayar: <ul><li>Bulan-bulan SPP yang masih merah (belum lunas).</li><li>Tagihan bebas (Uang Gedung, Seragam, dll.) beserta sisa kekurangannya.</li></ul></li><li><strong>Centang tagihan yang ingin dibayar</strong>: <ul><li>Contoh: Centang <em>SPP Bulan Oktober (Rp 350.000)</em> dan masukkan cicilan <em>Uang Gedung (Rp 500.000)</em>.</li></ul></li><li>Sistem akan menjumlahkan total yang harus dibayar: <code>Rp 850.000</code>.</li><li>Masukkan nominal uang yang diterima di kolom <strong>Uang Tunai</strong>. Sistem akan otomatis menghitung uang kembalian.</li><li>Klik tombol <strong>Bayar Sekarang &amp; Cetak Kuitansi</strong>.</li></ol><hr><h2 id="_2-mencetak-ulang-kuitansi-pembayaran" tabindex="-1">2. Mencetak Ulang Kuitansi Pembayaran <a class="header-anchor" href="#_2-mencetak-ulang-kuitansi-pembayaran" aria-label="Permalink to &quot;2. Mencetak Ulang Kuitansi Pembayaran&quot;">​</a></h2><p>Jika kuitansi sebelumnya hilang atau printer kehabisan kertas:</p><ol><li>Buka menu <strong>Keuangan</strong> <strong>Riwayat Transaksi</strong>.</li><li>Cari transaksi berdasarkan nomor kuitansi atau nama siswa.</li><li>Klik tombol <strong>Cetak Ulang (Print)</strong> di baris transaksi tersebut.</li><li>Kuitansi dapat dicetak ke printer struk thermal (58mm/80mm) atau printer biasa ukuran A4/A5.</li></ol>',9)])])}const b=n(r,[["render",s]]);export{d as __pageData,b as default};
